# section, so an older build still has somewhere to put them.
ANCHORS = [
    "app.post(['/stripe/portal', '/api/stripe/portal']",
    "app.post(['/stripe/create-checkout-session', '/api/stripe/create-checkout-session']",
    "app.get(['/stripe/price-info', '/api/stripe/price-info']",
    "app.get(['/stripe/subscription-status', '/api/stripe/subscription-status']",
]
NEEDS = ('stripeReady', 'stripeClient', 'userData', 'encodeEmail', 'loadShareAliases')

def node_ok(text):
    """node --check on the result, so a broken insert never reaches the service."""
    fd, tmp = tempfile.mkstemp(suffix='.js')
    try:
        os.write(fd, text.encode('utf-8')); os.close(fd)
        r = subprocess.run(['node', '--check', tmp], capture_output=True, text=True)
        return (r.returncode == 0, (r.stderr or '').strip().split('\n')[0])
    except FileNotFoundError:
        return (True, '')
    finally:
        try: os.unlink(tmp)
        except OSError: pass

BEGIN = '// <<baja-fundraise %s %s>>'
END = '// <</baja-fundraise %s>>'
BEGIN_RE = r'^// <<baja\-fundraise ([a-z0-9\-]+) ([0-9a-f]{8})>>$'


def wrapped(text, pid):
    """Where this piece's block starts and ends, and the hash it was written with.

    A block carries its own id and a hash of what went in, so a later run can tell "this is
    already here" from "this is here but out of date" -- which the first version of this
    installer could not, and so left a server running an endpoint from a week ago while
    reporting that everything was already installed."""
    import re
    for m in re.finditer(BEGIN_RE, text, flags=re.M):
        if m.group(1) != pid:
            continue
        close = END % pid
        j = text.find(close, m.end())
        if j < 0:
            return None
        return (m.start(), j + len(close) + 1, m.group(2))
    return None


def drop_legacy(text):
    """Take out the bodies earlier versions of this installer inserted, exactly as written.

    Matched byte for byte rather than found by shape: this deletes code, and the only safe
    rule is that the text either is something this installer wrote or it is not. What comes
    out here goes back in below, current and marked, so a server patched a week ago ends up
    with exactly the file a clean one gets."""
    import re
    def spans(t):
        out = []
        for m in re.finditer(BEGIN_RE, t, flags=re.M):
            close = END % m.group(1)
            j = t.find(close, m.end())
            if j >= 0:
                out.append((m.start(), j + len(close)))
        return out

    n, again = 0, True
    while again:
        again = False
        inside = spans(text)
        for body in LEGACY:
            start = 0
            while True:
                at = text.find(body, start)
                if at < 0:
                    break
                # A body that sits inside a marked block is this installer's own current
                # work, not a leftover: taking it out would leave the markers around a hole.
                if any(a <= at and at + len(body) <= b for a, b in inside):
                    start = at + 1
                    continue
                end = at + len(body)
                if text[end:end + 1] == '\n':      # the blank line that went in with it
                    end += 1
                text = text[:at] + text[end:]
                n += 1
                again = True
                break
            if again:
                break
    return text, n


def patch(path_, key, check):
    raw = open(path_, encoding='utf-8', newline='').read()
    crlf = '\r\n' in raw
    s = raw.replace('\r\n', '\n')
    for need in NEEDS:
        if need not in s:
            sys.exit(path_ + ' has no ' + need + ', so this is not the file with the Stripe section in'
                     ' it. Nothing was changed.')
    s, stale = drop_legacy(s)
    added, updated, same = [], [], []
    for piece in PIECES:
        pid, body = piece['id'], piece[key]
        block = (BEGIN % (pid, piece['hash_' + key])) + '\n' + body.rstrip('\n') + '\n' + (END % pid) + '\n'
        found = wrapped(s, pid)
        if found:
            a, b, had = found
            if had == piece['hash_' + key]:
                same.append(pid)
                continue
            s = s[:a] + block + s[b:]
            updated.append(pid)
            continue
        for a in piece.get('anchors', ANCHORS):
            if s.count(a) == 1:
                at = s.index(a)
                head = s.rfind('\n\n', 0, at)   # back up above the route's own comment block
                at = (head + 2) if head > 0 else at
                s = s[:at] + block + '\n' + s[at:]
                added.append(pid)
                break
        else:
            sys.exit('Could not find where ' + pid + ' goes in ' + path_ + '. Nothing was changed.')
    if stale:
        updated.extend(added)      # it was already here, unmarked; this is a replacement
        added = []
    if same and not (added or updated):
        print('Already up to date:', ', '.join(same), 'in', path_)
        return None
    if check:
        ok, why = node_ok(s)
        if not ok:
            sys.exit('The patched ' + path_ + ' does not parse (' + why + '). Nothing was changed.')
    what = []
    if added:
        what.append('added ' + ', '.join(added))
    if updated:
        what.append('updated ' + ', '.join(updated))
    if same:
        what.append(str(len(same)) + ' already current')
    return (path_, s, crlf, what)


root = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '/opt/baja-server')
dist = os.path.join(root, 'dist/index.js')
srcf = os.path.join(root, 'src/index.ts')
if not os.path.isfile(dist):
    sys.exit('Not found: ' + dist + '  (pass the baja-server directory as the first argument)')

writes = [w for w in [patch(dist, 'js', True)] if w]
if os.path.isfile(srcf):
    w = patch(srcf, 'ts', False)     # TypeScript: node --check cannot read it
    if w: writes.append(w)
else:
    print('No src/index.ts here, so only dist was considered. A rebuild from source elsewhere needs the'
          ' matching commit in baja-server.')

for p_, text, crlf, what in writes:
    # The first backup is the file as it was before any of this was ever installed, and it is
    # never overwritten -- that is the one worth having. Every run also leaves the immediately
    # previous file beside it.
    if not os.path.exists(p_ + '.before-donation'):
        shutil.copyfile(p_, p_ + '.before-donation')
    shutil.copyfile(p_, p_ + '.prev-donation')
    open(p_, 'w', encoding='utf-8', newline='').write(text.replace('\n', '\r\n') if crlf else text)
    print('Wrote', p_ + ':', '; '.join(what))
if writes:
    print('Now:  sudo systemctl restart baja-server')
    print('Then: curl -s localhost:8080/stripe/donation-session')
else:
    print('Nothing to do.')
